// ESLint, with typescript-eslint's recommended rules for the TypeScript in src/
// and test/. Run with `npm run lint`.

import eslint from "@eslint/js"
import tseslint from "typescript-eslint"

export default tseslint.config(
  {
    ignores: [
      "dist/",
      "docs/",                  // its own project, with its own JavaScript
      "extras/",                // editor and site plugins, each its own project
      "node_modules/",
      "src/peg_parser/jp*.js",  // generated by Peggy from jp.pegjs
      "src/peg_parser/*.d.ts",
    ],
  },
  {
    files: ["src/**/*.ts", "test/**/*.ts"],
    extends: [
      eslint.configs.recommended,
      tseslint.configs.recommended,
    ],
    rules: {
      // A leading underscore marks a parameter or variable that is
      // deliberately unused, such as the interpreter passed to every builtin.
      "@typescript-eslint/no-unused-vars": ["error", {
        argsIgnorePattern: "^_",
        varsIgnorePattern: "^_",
        caughtErrorsIgnorePattern: "^_",
        destructuredArrayIgnorePattern: "^_",
      }],
      // picjs values are TA, shape parameters ShapeParams, and anything
      // whose type is truly open is unknown, checked where it's used
      "@typescript-eslint/no-explicit-any": "error",
    },
  },
  {
    // Tests reach into internals, and `any` is the honest way to do that
    files: ["test/**/*.ts"],
    rules: {
      "@typescript-eslint/no-explicit-any": "off",
    },
  },
)
